"""
mkdir -p star
for f in input_index/*; do
    name=\$(basename "\$f")
    if [ "\$name" = "genomeParameters.txt" ]; then
        continue
    fi
    cp -r "\$(readlink -f "\$f")" "star/\$name"
done

awk -F'\\t' -v OFS='\\t' '
    \$1 == "versionGenome" && \$2 == "20201" {
        print "versionGenome", "2.7.4a"
        seen_upgraded = 1
        next
    }
    \$1 == "genomeType"          { seen_genomeType = 1 }
    \$1 == "genomeTransformType" { seen_transformType = 1 }
    \$1 == "genomeTransformVCF"  { seen_transformVCF = 1 }
    { print }
    END {
        if (seen_upgraded) {
            if (!seen_genomeType)    print "genomeType", "Full"
            if (!seen_transformType) print "genomeTransformType", "None"
            if (!seen_transformVCF)  print "genomeTransformVCF", "-"
        }
    }
' "input_index/genomeParameters.txt" > star/genomeParameters.txt
"""

def args = task.ext.args ?: ''
def prefix = task.ext.prefix ?: "${meta.id}"

def avail_mem = 3072
if (!task.memory) {
    log.info '[BBSplit] Available memory not known - defaulting to 3GB. Specify process memory requirements to change this.'
} else {
    avail_mem = (task.memory.mega*0.8).intValue()
}

def other_refs = []
other_ref_names.eachWithIndex { name, idx ->
    other_refs << "ref_${name}=${other_ref_paths[idx]}"
}

def fastq_in=''
def fastq_out=''
def index_files=''
def refstats_cmd=''
def use_index = index ? true : false

if (only_build_index) {
    if (primary_ref && other_ref_names && other_ref_paths) {
        index_files = 'ref_primary=' +primary_ref + ' ' + other_refs.join(' ') + ' path=bbsplit_build'
    } else {
        log.error 'ERROR: Please specify as input a primary fasta file along with names and paths to non-primary fasta files.'
    }
} else {
    if (index) {
        index_files = "path=index_writable"
    } else if (primary_ref && other_ref_names && other_ref_paths) {
        index_files = "ref_primary=${primary_ref} ${other_refs.join(' ')}"
    } else {
        log.error 'ERROR: Please either specify a BBSplit index as input or a primary fasta file along with names and paths to non-primary fasta files.'
    }
    fastq_in  = meta.single_end ? "in=${reads}" : "in=${reads[0]} in2=${reads[1]}"
    fastq_out = meta.single_end ? "basename=${prefix}_%.fastq.gz" : "basename=${prefix}_%_#.fastq.gz"
    refstats_cmd = 'refstats=' + prefix + '.stats.txt'
}
"""

# If using a pre-built index, create writable structure: symlink all files except
# summary.txt (which we copy to modify). When we stage in the index files the time
# stamps get disturbed, which bbsplit doesn't like. Fix the time stamps in summaries.
if [ "$use_index" == "true" ]; then
    find input_index/ref -type f | while read -r f; do
        target="index_writable/\${f#input_index/}"
        mkdir -p "\$(dirname "\$target")"
        [[ \$(basename "\$f") == "summary.txt" ]] && cp "\$f" "\$target" || ln -s "\$(realpath "\$f")" "\$target"
    done
    find index_writable/ref/genome -name summary.txt | while read -r summary_file; do
        src=\$(grep '^source' "\$summary_file" | cut -f2- -d\$'\\t' | sed 's|.*/ref/|index_writable/ref/|')
        mod=\$(echo "System.out.println(java.nio.file.Files.getLastModifiedTime(java.nio.file.Paths.get(\\"\$src\\")).toMillis());" | jshell -J-Djdk.lang.Process.launchMechanism=vfork - 2>/dev/null | grep -oE '^[0-9]{12,14}\$')
        sed -e 's|bbsplit_index/ref|index_writable/ref|' -e "s|^last modified.*|last modified\\t\$mod|" "\$summary_file" > \${summary_file}.tmp && mv \${summary_file}.tmp \${summary_file}
    done
fi

# Run BBSplit

bbsplit.sh \\
    -Xmx${avail_mem}M \\
    $index_files \\
    threads=$task.cpus \\
    $fastq_in \\
    $fastq_out \\
    $refstats_cmd \\
    $args 2>| >(tee ${prefix}.log >&2)

# Summary files will have an absolute path that will make the index
# impossible to use in other processes - fix paths and rename atomically
if [ -d bbsplit_build/ref/genome ]; then
    find bbsplit_build/ref/genome -name summary.txt | while read -r summary_file; do
        sed "s|^source.*|source\\t\$(grep '^source' "\$summary_file" | cut -f2- -d\$'\\t' | sed 's|.*/bbsplit_build|bbsplit_index|')|" "\$summary_file" > \${summary_file}.tmp && mv \${summary_file}.tmp \${summary_file}
    done
    mv bbsplit_build bbsplit_index
fi
"""

def args = task.ext.args ?: ''
def args_list = args.tokenize()
args += scale > 0 && scale != 1 ? " -scale ${scale}" : ""
if (!args_list.contains('-bg') && (scale > 0 && scale != 1)) {
    args += " -bg"
}


def buffer = task.memory ? "--buffer-size=${task.memory.toGiga().intdiv(2)}G" : ''
def sort_cmd = sort ? "| LC_ALL=C sort --parallel=${task.cpus} ${buffer} -k1,1 -k2,2n" : ''

def prefix = task.ext.prefix ?: "${meta.id}"
if (intervals.name =~ /\.bam/) {
    """
    bedtools \\
        genomecov \\
        -ibam ${intervals} \\
        ${args} \\
        ${sort_cmd} \\
        > ${prefix}.${extension}
    """
}
else {
    """
    bedtools \\
        genomecov \\
        -i ${intervals} \\
        -g ${sizes} \\
        ${args} \\
        ${sort_cmd} \\
        > ${prefix}.${extension}
    """
}

def prefix = task.ext.prefix ?: "${meta.id}"
def readList = reads instanceof List ? reads.collect { item -> item.toString() } : [reads.toString()]
def compress = readList[0]?.endsWith('.gz') ? '' : '| gzip'
if (meta.single_end) {
    if (readList.size >= 1) {
        """
        cat ${readList.join(' ')} ${compress} > ${prefix}.merged.fastq.gz
        """
    } else {
        error("Could not find any FASTQ files to concatenate in the process input")
    }
}
else {
    if (readList.size >= 2) {
        def read1 = []
        def read2 = []
        readList.eachWithIndex { v, ix -> (ix & 1 ? read2 : read1) << v }
        """
        cat ${read1.join(' ')} ${compress} > ${prefix}_1.merged.fastq.gz
        cat ${read2.join(' ')} ${compress} > ${prefix}_2.merged.fastq.gz
        """
    } else {
        error("Could not find any FASTQ file pairs to concatenate in the process input")
    }
}

def args = task.ext.args ?: ''
def prob_exists = args =~ /-p|--probability/
def nrec_exists = args =~ /-n|--record-count/
if ( !(prob_exists || nrec_exists) ){
    error "FQ/SUBSAMPLE requires --probability (-p) or --record-count (-n) specified in task.ext.args!"
}
def prefix = task.ext.prefix ?: "${meta.id}"
def n_fastq = fastq instanceof List ? fastq.size() : 1
log.debug "FQ/SUBSAMPLE found ${n_fastq} FASTQ files"
if ( n_fastq == 1 ){
    fastq1_output = "--r1-dst ${prefix}.fastq.gz"
    fastq2_output = ""
} else if ( n_fastq == 2 ){
    fastq1_output = "--r1-dst ${prefix}_R1.fastq.gz"
    fastq2_output = "--r2-dst ${prefix}_R2.fastq.gz"
} else {
    error "FQ/SUBSAMPLE only accepts 1 or 2 FASTQ files!"
}
"""
fq subsample \\
    $args \\
    $fastq \\
    $fastq1_output \\
    $fastq2_output
"""

def args = task.ext.args ?: ''

if (!task.memory) {
    error("[HISAT2 index build] No memory specified for process. Please configure memory for 'process_high' label.")
}
def avail_mem = task.memory.toGiga()
def hisat2_build_memory = hisat2_memory_input ? (hisat2_memory_input as MemoryUnit).toGiga() : Integer.MAX_VALUE

def ss = ''
def exon = ''
def extract_exons = ''

if (avail_mem >= hisat2_build_memory) {
    log.info("[HISAT2 index build] ${avail_mem} GB available, using splice sites and exons to build HISAT2 index")
    extract_exons = gtf ? "hisat2_extract_exons.py ${gtf} > ${gtf.baseName}.exons.txt" : ""
    ss = splicesites ? "--ss ${splicesites}" : ""
    exon = gtf ? "--exon ${gtf.baseName}.exons.txt" : ""
}
else {
    log.info("[HISAT2 index build] Only ${avail_mem} GB available (< ${hisat2_build_memory} GB threshold), so NOT using splice sites and exons to build HISAT2 index.")
    log.info("[HISAT2 index build] Increase memory allocation or lower --hisat2_build_memory to enable splice-aware indexing.")
}

"""
mkdir hisat2
${extract_exons}
hisat2-build \\
    -p ${task.cpus} \\
    ${ss} \\
    ${exon} \\
    ${args} \\
    ${fasta} \\
    hisat2/${fasta.baseName}
"""

def args = task.ext.args ?: ''
prefix = task.ext.prefix ?: "${meta.id}"
extension = args.contains("--output-fmt sam")
    ? "sam"
    : args.contains("--output-fmt cram")
        ? "cram"
        : "bam"
def reference = fasta ? "--reference ${fasta}" : ""

def write_index = ""
def output_file = "${prefix}.${extension}"


if (index_format != '' && index_format) {
    write_index = "--write-index"
    output_file = "${prefix}.${extension}##idx##${prefix}.${extension}.${index_format}"
}
def is_sam = (bam instanceof List ? bam[0] : bam).name.endsWith('.sam')
if (index_format) {
    if (!index_format.matches('bai|csi|crai')) {
        error("Index format not one of bai, csi, crai.")
    }
    else if (extension == "sam") {
        error("Indexing not compatible with SAM output")
    }
}
if ("${bam}" == "${prefix}.bam") {
    error("Input and output names are the same, use \"task.ext.prefix\" to disambiguate!")
}
if ("${bam}" == "${prefix}.bam") {
    error("Input and output names are the same, use \"task.ext.prefix\" to disambiguate!")
}

def input_source = is_sam ? "${bam}" : "-"
def pre_command = is_sam ? "" : "samtools cat ${bam} | "

"""
${pre_command}samtools sort \\
    ${args} \\
    -T ${prefix} \\
    --threads ${task.cpus} \\
    ${reference} \\
    -o ${output_file} \\
    ${write_index} \\
    ${input_source}
"""

def args      = task.ext.args ?: ''
def args2     = task.ext.args2 ?: ''
prefix        = task.ext.prefix ?: "${meta.id}"
def reference = annotation_gtf ? "-G $annotation_gtf" : ""
def ballgown  = annotation_gtf ? "-b ${prefix}.ballgown" : ""
def coverage  = annotation_gtf ? "-C ${prefix}.coverage.gtf" : ""


if (!srbam && !lrbam) {
    error "At least one of srbam or lrbam must be provided for ${meta.id}"
}


def run_mode = ''
if (mode) {
    def valid_modes = ['expression-estimation', 'long-reads-assembly', 'mix-reads-assembly', 'nascent-aware-assembly']
    def modes = (mode instanceof List) ? mode :
                (mode instanceof String) ? mode.toString().split(',').collect { x -> x.trim() } : []
    modes.each { m ->
        if (!(m in valid_modes)) {
            error "Invalid mode: ${m}. Valid options are: ${valid_modes.join(', ')}"
        }
    }


    if (modes.contains('mix-reads-assembly') && !(srbam && lrbam)) {
        error "mode 'mix-reads-assembly' requires both srbam and lrbam to be provided for ${meta.id}"
    }
    if (modes.contains('long-reads-assembly') && !lrbam) {
        error "mode 'long-reads-assembly' requires lrbam to be provided for ${meta.id}"
    }
    if (modes.contains('expression-estimation') && !annotation_gtf) {
        error "mode 'expression-estimation' (-e) requires annotation_gtf to be provided for ${meta.id}"
    }


    def mode_flags = []
    if (modes.contains('expression-estimation')) {
        mode_flags += (lrbam && !srbam) ? ['-L', '-e'] : ['-e']
    }
    if (modes.contains('long-reads-assembly') && !modes.contains('expression-estimation')) {
        mode_flags += '-L'
    }
    if (modes.contains('mix-reads-assembly')) {
        mode_flags += '--mix'
    }
    if (modes.contains('nascent-aware-assembly')) {
        mode_flags += ['-N', '--nasc']
    }

    run_mode = mode_flags.join(' ')
}


def bam_inputs = (srbam && lrbam) ? "$srbam $lrbam" : (srbam ? "$srbam" : "$lrbam")
"""
stringtie \\
    -o ${prefix}.transcripts.gtf \\
    ${run_mode} \\
    ${args2} \\
    ${reference} \\
    -A ${prefix}.gene.abundance.txt \\
    ${coverage} \\
    ${ballgown} \\
    -p ${task.cpus} \\
    ${bam_inputs} \\
    ${args}
"""

def args = task.ext.args ?: ''



def cores = 1
if (task.cpus) {
    cores = (task.cpus as int) - 4
    if (meta.single_end) {
        cores = (task.cpus as int) - 3
    }
    if (cores < 1) {
        cores = 1
    }
    if (cores > 8) {
        cores = 8
    }
}


def prefix = task.ext.prefix ?: "${meta.id}"
if (meta.single_end) {
    def args_list = args.split("\\s(?=--)").toList()
    args_list.removeAll { arg -> arg.toLowerCase().contains('_r2 ') }
    """
    [ ! -f  ${prefix}.fastq.gz ] && ln -s ${reads} ${prefix}.fastq.gz
    trim_galore \\
        ${args_list.join(' ')} \\
        --cores ${cores} \\
        --gzip \\
        ${prefix}.fastq.gz
    """
}
else {
    """
    [ ! -f  ${prefix}_1.fastq.gz ] && ln -s ${reads[0]} ${prefix}_1.fastq.gz
    [ ! -f  ${prefix}_2.fastq.gz ] && ln -s ${reads[1]} ${prefix}_2.fastq.gz
    trim_galore \\
        ${args} \\
        --cores ${cores} \\
        --paired \\
        --gzip \\
        ${prefix}_1.fastq.gz \\
        ${prefix}_2.fastq.gz
    """
}

